<script setup lang="ts">
import{computed,onMounted,ref}from"vue";import{ElMessage,ElMessageBox}from"element-plus";import{api}from"../utils/api";
import { useClientPagination } from "../composables/useClientPagination";
const POSTING_STATUS={POSTED:2,VOID:3}as const;const postingLabels:Record<number,string>={2:"\u5df2\u8bb0\u8d26",3:"\u4f5c\u5e9f"};
const periods=ref<any[]>([]),accounts=ref<any[]>([]),rows=ref<any[]>([]),periodId=ref<number | "">(""),loading=ref(false);const {page,pageSize,total,pagedRows,resetPage}=useClientPagination(rows);const form=ref({expenseAccountId:"" as number | "",accumulatedDepreciationAccountId:"" as number | ""});const accumulatedDepreciationAccounts=computed(()=>accounts.value.filter(a=>a.code==="1602"&&a.isEnabled&&a.isLeaf));function money(value:unknown){return Number(value??0).toFixed(2);}async function support(){[periods.value,accounts.value]=await Promise.all([api.get<any[]>("/accounting-periods"),api.get<any[]>("/accounts?tree=false")]);form.value.accumulatedDepreciationAccountId=accumulatedDepreciationAccounts.value[0]?.id??"";if(periods.value[0]){periodId.value=periods.value[0].id;await load();}}async function load(){if(!periodId.value)return;loading.value=true;try{rows.value=await api.get<any[]>(`/depreciations?periodId=${periodId.value}`);}finally{loading.value=false;}}function accountPayload(){if(!form.value.accumulatedDepreciationAccountId){ElMessage.warning("未找到可用的1602累计折旧科目");return null;}return{accumulatedDepreciationAccountId:form.value.accumulatedDepreciationAccountId,...(form.value.expenseAccountId?{expenseAccountId:form.value.expenseAccountId}:{})};}async function accrue(){const payload=accountPayload();if(!payload)return;await api.post(`/depreciations/${periodId.value}/accrue`,payload);await load();}async function cancel(row:any){const{value}=await ElMessageBox.prompt("请输入撤销原因","撤销折旧",{inputPattern:/\S+/,inputErrorMessage:"原因不能为空"});await api.post(`/depreciations/records/${row.id}/cancel`,{reason:value});await load();}async function reaccrue(row:any){const payload=accountPayload();if(!payload)return;await api.post(`/depreciations/records/${row.id}/reaccrue`,payload);await load();}onMounted(support);
</script>
<template><div class="page-grid"><section class="page-heading"><div><h2>自动折旧</h2><p>按会计期间计提平均年限法折旧，支持撤销和重新计提。</p></div></section><el-card shadow="never"><div class="toolbar"><el-select v-model="periodId" style="width:160px" @change="resetPage(); load()"><el-option v-for="p in periods" :key="p.id" :label="p.periodCode" :value="p.id"/></el-select><el-select v-model="form.expenseAccountId" clearable filterable placeholder="默认折旧费用科目（可选）" style="width:250px"><el-option v-for="a in accounts" :key="a.id" :label="`${a.code} ${a.name}`" :value="a.id"/></el-select><el-select v-model="form.accumulatedDepreciationAccountId" placeholder="累计折旧科目（必选）" style="width:220px"><el-option v-for="a in accumulatedDepreciationAccounts" :key="a.id" :label="`${a.code} ${a.name}`" :value="a.id"/></el-select><el-button type="primary" @click="accrue">计提折旧</el-button></div></el-card><el-card shadow="never"><el-table table-layout="auto" v-loading="loading" :data="pagedRows" stripe><el-table-column prop="asset.assetNo" label="资产编号"/><el-table-column prop="asset.name" label="资产名称"/><el-table-column prop="period.periodCode" label="期间"/><el-table-column label="折旧金额"><template #default="scope">{{ money(scope.row.amount) }}</template></el-table-column><el-table-column label="状态"><template #default="scope">{{ postingLabels[scope.row.status] ?? scope.row.status }}</template></el-table-column><el-table-column prop="voucher.voucherNo" label="凭证号"/><el-table-column label="操作"><template #default="scope"><el-button v-if="scope.row.status===POSTING_STATUS.POSTED" text type="danger" @click="cancel(scope.row)">撤销</el-button><el-button v-else text type="primary" @click="reaccrue(scope.row)">重新计提</el-button></template></el-table-column></el-table><PaginationBar v-model:page="page" v-model:page-size="pageSize" :total="total"/></el-card></div></template>
